[profile.default]
retries = 0
fail-fast = true
slow-timeout = { period = "90s", terminate-after = 2 }

[test-groups]
generated-contract = { max-threads = 1 }
postgres-integration = { max-threads = 1 }
redis-integration = { max-threads = 1 }
nats-integration = { max-threads = 2 }
minio-integration = { max-threads = 1 }

[[profile.default.overrides]]
filter = "package(omnius-test-support) & test(/postgres_container/)"
test-group = "postgres-integration"

[[profile.default.overrides]]
filter = "package(omnius-test-support) & test(/redis_container/)"
test-group = "redis-integration"

[[profile.default.overrides]]
filter = "package(omnius-test-support) & test(/nats_container/)"
test-group = "nats-integration"

[[profile.default.overrides]]
filter = "package(omnius-test-support) & test(/minio_container/)"
test-group = "minio-integration"

{% if "postgres" in modules %}
[[profile.default.overrides]]
filter = "package(omnius-postgres) & kind(test)"
test-group = "postgres-integration"

{% endif %}

{% if "migrations" in modules %}
[[profile.default.overrides]]
filter = "package(omnius-migrations) & kind(test)"
test-group = "postgres-integration"
{% endif %}

{% if "idempotency" in modules %}
[[profile.default.overrides]]
filter = "package(omnius-idempotency) & kind(test)"
test-group = "postgres-integration"
{% endif %}


{% if "auth-api-key" in modules %}
[[profile.default.overrides]]
filter = "package(omnius-auth-api-key) & binary(api_keys)"
test-group = "postgres-integration"
{% endif %}

{% if "auth-password" in modules %}
[[profile.default.overrides]]
filter = "package(omnius-auth-password) & (binary(registration) | binary(postgres))"
test-group = "postgres-integration"
{% endif %}

{% if "auth-session-postgres" in modules %}
[[profile.default.overrides]]
filter = "package(omnius-auth-session-postgres) & binary(session_flow)"
test-group = "postgres-integration"
{% endif %}

[[profile.default.overrides]]
filter = "all()"
test-group = "generated-contract"

